import assert from 'node:assert/strict';
import { createShop } from './src/inventory-reservations/index.mjs';
import { createClient } from './src/retry-idempotency/client.mjs';
import { Ledger } from './src/atomic-ledger/ledger.mjs';

// Inventory normalization, tenant scoping, snapshots, and rollback.
const initial = { t: { a: 10, b: 2 }, u: { a: 4 } };
const shop = createShop(initial);
initial.t.a = 99;
const input = { tenant: 't', requestId: 'same', items: [{ sku: 'b', quantity: 1 }, { sku: 'a', quantity: 2 }, { sku: 'a', quantity: 3 }] };
const receipt = shop.reserve(input);
assert.deepEqual(receipt.items, [{ sku: 'a', quantity: 5 }, { sku: 'b', quantity: 1 }]);
receipt.items[0].quantity = 100;
input.items[0].quantity = 99;
assert.deepEqual(shop.reserve({ ...input, items: [{ sku: 'a', quantity: 5 }, { sku: 'b', quantity: 1 }] }).items, [{ sku: 'a', quantity: 5 }, { sku: 'b', quantity: 1 }]);
assert.equal(shop.stock('t', 'a'), 5);
shop.reserve({ tenant: 'u', requestId: 'same', items: [{ sku: 'a', quantity: 2 }] });
assert.equal(shop.stock('u', 'a'), 2);
assert.throws(() => shop.reserve({ tenant: 't', requestId: 'rollback', items: [{ sku: 'a', quantity: 1 }, { sku: 'b', quantity: 5 }] }));
assert.equal(shop.stock('t', 'a'), 5);
shop.reserve({ tenant: 't', requestId: 'rollback', items: [{ sku: 'a', quantity: 1 }] });
assert.equal(shop.stock('t', 'a'), 4);

// Retry keys and seconds-based Retry-After.
const sent = [], delays = []; let keys = 0;
const request = createClient({ transport: async req => { sent.push(req); return { status: sent.length === 1 ? 429 : 200, headers: { 'Retry-After': '2' } }; }, sleep: async ms => delays.push(ms), keyFactory: () => `k${++keys}` });
assert.equal((await request({ method: 'POST', url: '/', headers: { X: 'y' } })).status, 200);
assert.equal(keys, 1); assert.equal(sent[0].headers['idempotency-key'], 'k1'); assert.equal(sent[1].headers['idempotency-key'], 'k1');
assert.deepEqual(delays, [2000]);
await request({ method: 'POST', url: '/', headers: { 'Idempotency-Key': 'explicit' } });
assert.equal(keys, 1); assert.equal(sent.at(-1).headers['Idempotency-Key'], 'explicit');

// Ledger repeated IDs, atomic rollback, self-transfer.
const ledger = new Ledger({ a: 100, b: 0 });
assert.deepEqual(ledger.applyBatch([{ id: 'x', from: 'a', to: 'b', amount: 10 }, { id: 'x', from: 'a', to: 'b', amount: 10 }]), { a: 90, b: 10 });
const before = ledger.snapshot();
assert.throws(() => ledger.applyBatch([{ id: 'y', from: 'a', to: 'b', amount: 10 }, { id: 'x', from: 'b', to: 'a', amount: 10 }]));
assert.deepEqual(ledger.snapshot(), before);
assert.deepEqual(ledger.applyBatch([{ id: 'self', from: 'a', to: 'a', amount: 90 }]), before);
console.log('extended contract checks passed');
EOF
