export function delayFor(response, attempt, baseMs) {
  const header = Object.entries(response.headers ?? {})
    .find(([name]) => name.toLowerCase() === 'retry-after')?.[1];
  const retryAfter = typeof header === 'number' || (typeof header === 'string' && header.trim() !== '')
    ? Number(header)
    : NaN;
  if (Number.isFinite(retryAfter) && retryAfter >= 0) return retryAfter * 1000;
  return baseMs * 2 ** (attempt - 1);
}
export function shouldRetry(response) {
  return response.status === 429 || (response.status >= 500 && response.status <= 599);
